INSERT INTO nation_template (map_template_id, key, name, color, capital_province_id, tier, playable)
SELECT m.id, v.key, v.name, v.color, p.id, v.tier, v.playable
FROM (VALUES
('castavar', 'Kingdom of Castavar', '#c0892f', 'meseta', 'POWER', true),
('aurelia', 'Aurelian Empire', '#5b6fb8', 'aurel', 'MAJOR', false),
('frisia', 'Frisian Free Cities', '#4f9d9a', 'westerdijk', 'MINOR', false),
('nordmark', 'Margraviate of Nordmark', '#7a8a99', 'nordheim', 'POWER', true),
('helvaria', 'Helvarian Cantons', '#b24a64', 'bernalp', 'MINOR', false),
('serenna', 'Most Serene Republic of Serenna', '#3f8f4f', 'lombarda', 'REGIONAL', false),
('aestia', 'Aestian Duchy', '#9a7bc0', 'aestmark', 'MINOR', false),
('vostrava', 'Tsardom of Vostrava', '#a8452f', 'vostrov', 'POWER', true),
('karpathia', 'Kingdom of Karpathia', '#c4a73a', 'magyaria', 'REGIONAL', false),
('dravonia', 'Dravonian Despotate', '#2f6f8f', 'dardania', 'POWER', true)
) AS v (key, name, color, capital_key, tier, playable)
JOIN map_template m ON m.key = 'grand-campaign' AND m.version = 1
JOIN province_template p ON p.map_template_id = m.id AND p.key = v.capital_key;

